// Read static data to find last processed build number
const staticData = $getWorkflowStaticData('global');
const lastProcessed = staticData.lastBuildTmn || 0;
const latestBuild = $input.first().json.number;

if (!latestBuild || latestBuild <= lastProcessed) {
  return []; // no new builds — stop workflow
}

// Generate one item per new build
const BASE_URL = 'https://jenkins-ops.private-a-cloud1p.ascendmoney.io/job/acm-config-server-sms-notification';
const items = [];
for (let n = lastProcessed + 1; n <= latestBuild; n++) {
  items.push({
    json: {
      buildNumber: n,
      latestBuild,
      buildUrl: `${BASE_URL}/${n}/api/json`
    }
  });
}
return items;

const GATEWAY_MAP = {
  FH:     'Firt-hop',
  IFB_HK: 'Infobip HK',
  IFB_SG: 'Infobip SG'
};

function getParam(actions, paramName) {
  for (const action of (actions || [])) {
    if (action._class === 'hudson.model.ParametersAction') {
      for (const p of (action.parameters || [])) {
        if (p.name === paramName) return p.value;
      }
    }
  }
  return null;
}

function getTriggeredBy(actions) {
  for (const action of (actions || [])) {
    if (action._class === 'hudson.model.CauseAction') {
      return action.causes?.[0]?.userName || '';
    }
  }
  return '';
}

function toBangkokISO(ms) {
  const d = new Date(ms + 7 * 3600 * 1000);
  return d.toISOString().replace('Z', '+07:00');
}

const prevBuild    = $input.first().json;
const currentBuild = $('Jenkins — Get Build Details').item.json;

const toVal   = getParam(currentBuild.actions, 'presets');
const fromVal = getParam(prevBuild.actions, 'presets') || toVal;

return [{
  json: {
    project:      'tmn',
    build_number: currentBuild.number,
    switch_start: toBangkokISO(currentBuild.timestamp),
    switch_end:   toBangkokISO(currentBuild.timestamp + currentBuild.duration),
    from_gateway: GATEWAY_MAP[fromVal] || fromVal || 'Unknown',
    to_gateway:   GATEWAY_MAP[toVal]   || toVal   || 'Unknown',
    triggered_by: getTriggeredBy(currentBuild.actions),
    latestBuild:  currentBuild.number
  }
}];

// Update static data so next run knows where to start
const staticData = $getWorkflowStaticData('global');
const items = $input.all();
const latest = Math.max(...items.map(i => i.json?.latestBuild || 0));
if (latest > 0) staticData.lastBuildTmn = latest;
return items;
